import{_ as a,C as r,o as s,c as i,j as t,a as n,E as h,a6 as d}from"./chunks/framework.CCKCzdWs.js";const c="/screenshots/picker-pause.png",k=JSON.parse('{"title":"Breakpoints in the browser","description":"Set a breakpoint in VS Code or a JetBrains IDE and the next test run Piwi starts pauses there in a headed browser, with a bar to resume, step, pick a locator that replaces the one on that line, or record the steps that come next.","frontmatter":{"title":"Breakpoints in the browser","description":"Set a breakpoint in VS Code or a JetBrains IDE and the next test run Piwi starts pauses there in a headed browser, with a bar to resume, step, pick a locator that replaces the one on that line, or record the steps that come next.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/editor-breakpoints.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/editor-breakpoints.html"}],["meta",{"property":"og:title","content":"Breakpoints in the browser | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Set a breakpoint in VS Code or a JetBrains IDE and the next test run Piwi starts pauses there in a headed browser, with a bar to resume, step, pick a locator that replaces the one on that line, or record the steps that come next."}]]},"headers":[],"relativePath":"features/editor-breakpoints.md","filePath":"features/editor-breakpoints.md","lastUpdated":1792865852000}'),l={name:"features/editor-breakpoints.md"};function p(u,e,g,b,f,m){const o=r("Needs");return s(),i("div",null,[e[0]||(e[0]=t("h1",{id:"breakpoints-in-the-browser",tabindex:"-1"},[n("Breakpoints in the browser "),t("a",{class:"header-anchor",href:"#breakpoints-in-the-browser","aria-label":'Permalink to "Breakpoints in the browser"'},"​")],-1)),h(o,{reporter:"",fixtures:""}),e[1]||(e[1]=d('<p>A breakpoint you set with the editor&#39;s own gutter click pauses the next test run the <a href="./editors.html">editor extensions</a> start, in the browser, right before the locator action or assertion on its line. Piwi&#39;s bar at the top of the page lets you look at the page, step through the actions, or pick a better locator, which lands back on that line in the editor. It is not Playwright&#39;s inspector, and no debugger attaches: the test waits in the browser.</p><h2 id="pause-a-run" tabindex="-1">Pause a run <a class="header-anchor" href="#pause-a-run" aria-label="Permalink to &quot;Pause a run&quot;">​</a></h2><ol><li>Set a line breakpoint on a line that calls a locator, in a spec or a page object: <code>await page.getByText(&#39;Pay now&#39;).click();</code>.</li><li>Run the test from Piwi: <strong>Run this test</strong>, the lines above a locator, <strong>Piwi: Run the tests that reach this file</strong>, <strong>Piwi: Run selection…</strong> or <strong>Re-run the failing tests</strong> (<a href="./editor-runs.html#run-tests">Runs from the editor</a>).</li><li>The run opens a headed browser. Before the action on your line runs, its element is highlighted and the pause bar appears: <code>Paused at login.spec.ts:42 · click · getByText(&#39;Pay now&#39;)</code>.</li></ol><table tabindex="0"><thead><tr><th>Button</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Resume</strong> (<kbd>Esc</kbd>)</td><td>Runs on to the next breakpoint</td></tr><tr><td><strong>Step</strong></td><td>Pauses again before the next locator action or assertion, breakpoint or not</td></tr><tr><td><strong>Pick a locator</strong></td><td>Opens Piwi&#39;s <a href="/features/locator-healing.html#pick-a-replacement-locator-on-the-failing-page-local-runs">element picker</a>: pick the element, choose stable parents, confirm a ranked locator; the bar comes back after</td></tr><tr><td><strong>Record here</strong></td><td>Records what you do in the page into the editor, above the paused line: <a href="#record-from-a-pause">Record from a pause</a></td></tr><tr><td><strong>Finish</strong></td><td>Runs on without pausing again in this test</td></tr></tbody></table><figure><img src="'+c+'" alt="A shop page in the browser, paused before a click on Checkout: the button highlighted, Piwi&#39;s pause bar at the top with Resume, Step, Pick a locator, Record here and Finish"><figcaption>A run paused before the click on <strong>Checkout</strong>: the element highlighted, and Piwi&#39;s bar at the top of the page.</figcaption></figure><p>The page under the bar stays live: scroll it, open the browser&#39;s developer tools, or click through it before you resume. The test timeout stops while the test is paused, and the test has the time it had left once it resumes.</p><h2 id="where-the-pick-lands" tabindex="-1">Where the pick lands <a class="header-anchor" href="#where-the-pick-lands" aria-label="Permalink to &quot;Where the pick lands&quot;">​</a></h2><p>A locator you confirm replaces the locator chain on the breakpoint&#39;s line, in the file as it stands, saved or not: <code>page.getByText(&#39;Pay now&#39;).click()</code> becomes <code>page.getByRole(&#39;button&#39;, { name: &#39;Pay now&#39; }).click()</code>, and a notification says so. When the line holds no locator, because you edited it during the pause or it takes its locator from a page object (<code>checkout.payButton().click()</code>), the locator is inserted at the cursor instead, and the notification says why.</p><p>The pick is also printed in the run&#39;s terminal (<code>[piwi] Locator picked at tests/login.spec.ts:42: getByRole(…)</code>) and recorded in the run&#39;s locator snapshots, so the <a href="/features/locator-healing.html">Locator fix</a> panel shows it as <strong>Your pick</strong> once the run uploads.</p><p>The run reaches the editor through the address <a href="./editor-recording.html#send-from-piwi-picker">Piwi Picker sends to</a>: VS Code starts its listener when a run with breakpoints starts, and the JetBrains plugin answers on the IDE&#39;s built-in server. Nothing is copied to the clipboard.</p><h2 id="record-from-a-pause" tabindex="-1">Record from a pause <a class="header-anchor" href="#record-from-a-pause" aria-label="Permalink to &quot;Record from a pause&quot;">​</a></h2><p><strong>Record here</strong> hands the paused page to the editor&#39;s <a href="./editor-recording.html">recorder</a>: the steps you take from there are written into the file on a new line above the paused statement (the first line of a statement broken over lines), on the page expression in scope there, as <strong>Record here</strong> in the editor writes them, but with no <code>page.goto</code>: the page is where the test left it, signed in and filled in as the test made it. The editor opens the file at that line and starts recording without asking anything. Pause and Stop are in the recorder&#39;s bar in the page and in the editor; once you stop, the pause bar comes back, and <strong>Resume</strong> runs the rest of the test from the page as you left it, which checks at once that the new steps fit what follows.</p><p><code>await page.pause()</code> in a test does the same without a breakpoint: in a run Piwi starts, it shows Piwi&#39;s pause bar there in place of Playwright&#39;s Inspector, with <strong>Record here</strong> among its buttons, and Piwi adds <code>--headed</code> to a run whose spec holds a <code>page.pause()</code> call. The <code>page.pause()</code> line stays, so the next run can record from there again; remove it when the test is done. In a run Piwi did not start, and in a headless one, <code>page.pause()</code> is Playwright&#39;s own. <strong>Record here</strong> records http(s) pages: on a page the test made with <code>setContent</code>, or a <code>file:</code> page, the editor says so and nothing is recorded.</p><p>The test reaches the editor through a socket on your machine that the editor service opens, readable by you only, named in the run&#39;s environment as <code>PIWI_RECORD_CHANNEL</code>. A recording the editor does not start within 30 seconds is refused, and the test goes on.</p><h2 id="the-setting" tabindex="-1">The setting <a class="header-anchor" href="#the-setting" aria-label="Permalink to &quot;The setting&quot;">​</a></h2><p>Breakpoints are on by default. Turn them off with the <code>piwi.breakpoints</code> setting in VS Code, or <strong>Pause the runs Piwi starts at the editor&#39;s breakpoints</strong> under <strong>Settings → Tools → Piwi</strong> in a JetBrains IDE, kept on your machine only. With the setting off, a run started from Piwi ignores the editor&#39;s breakpoints.</p><h2 id="what-it-needs" tabindex="-1">What it needs <a class="header-anchor" href="#what-it-needs" aria-label="Permalink to &quot;What it needs&quot;">​</a></h2><ul><li><strong><code>@piwitests/reporter</code> 0.48.0 or later</strong>, with the <a href="/guide/capture-fixtures.html">capture fixtures</a> in your tests: the pause runs in them. The status bar&#39;s tooltip names the reporter version the project installs. With an older one, the run starts anyway and the editor warns once: <code>Breakpoints need @piwitests/reporter 0.48.0 or later; this project has 0.46.0.</code></li><li><strong>A run started from Piwi.</strong> The editor passes the breakpoints under the Playwright config&#39;s folder to the run as <code>PIWI_PAUSE_AT</code> (<code>tests/login.spec.ts:42;tests/pages/checkout.page.ts:9</code>, relative to that folder, separated by semicolons), with its pairing address as <code>PIWI_EDITOR_SEND</code>, and adds <code>--headed</code> to the command unless it already has <code>--headed</code>, <code>--ui</code> or <code>--debug</code>. Set <code>PIWI_PAUSE_AT</code> yourself to <a href="/features/locator-healing.html#pause-at-a-breakpoint-local-runs">pause a run you start</a>.</li></ul><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Headed and local only.</strong> Under CI (<code>CI</code> set to anything but empty or <code>false</code>) or in a headless browser, the run ignores the breakpoints and says why once in its output.</li><li><strong>Only locator actions and assertions pause</strong>: <code>click()</code>, <code>fill()</code>, <code>expect(locator).toBeVisible()</code> and the like. A breakpoint on <code>page.goto</code>, on a helper call or on a line with no locator call does nothing. A breakpoint on the line of a page object method that runs an action pauses every test that calls the method.</li><li><strong>Every attempt pauses.</strong> With retries, a test pauses again on its retry, and the bar says <code>attempt 2</code>.</li><li><strong>Each worker pauses its own browser.</strong> When several tests reach a breakpoint, run them with <code>--workers=1</code> to pause one at a time.</li><li>Stepping through the test&#39;s JavaScript stays with the editor&#39;s own debugger and Playwright&#39;s; <strong>Record here</strong> is not offered from a debugger paused in your code, only from Piwi&#39;s pause bar.</li><li><strong>Record here</strong> records the paused page alone: a tab or a popup it opens is not recorded, as in any recording.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./editor-runs.html">Runs from the editor</a>: the commands that start a run, and how the editor follows it.</li><li><a href="/features/locator-healing.html">Locator healing</a>: the picker, and the panel a pick shows in.</li><li><a href="./editors.html">Editor extensions</a>: the failures, lenses and quick fixes the editor shows from your suite.</li></ul>',22))])}const y=a(l,[["render",p]]);export{k as __pageData,y as default};
